    "Tab strip and category rail on desktop, bottom nav on phones": "Pestañas y categorías en el escritorio; navegación inferior en teléfonos",
    "Test a list of servers": "Prueba una lista de servidores",
    "Test these servers": "Prueba estos servidores",
    "Testing…": "Probando…",
    "That address is a placeholder, not a server.":
        "Esa dirección es de relleno, no corresponde a un servidor.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Ese puerto usa HTTP sin cifrar, no TLS. Quita https:// (los paneles Xtream suelen usar http://host:8080). La aplicación ya reintenta con http; si ves este mensaje, ese intento también ha fallado.",
    "The account exists but its expiry date has passed.":
        "La cuenta existe pero su fecha de vencimiento ha pasado.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "El servidor no respondió. Causas habituales: nombre de host o puerto incorrectos, DNS mal configurado, cortafuegos o panel inactivo en ese puerto.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "El nombre de host corresponde a una dirección que no puede alojar un panel (Cloudflare usa 1.1.1.1 / 1.0.0.1 cuando un registro DNS no apunta a ningún servidor). Los datos enviados allí no llegan a un servidor, por lo que ni siquiera se transmiten el nombre de usuario y la contraseña. Solicita el host actual a quien te dio la dirección o pega su lista de hosts en «Probar una lista de servidores».",
    "The on-demand library": "La biblioteca bajo demanda",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "El panel respondió con HTTP {statusCode}, pero no devolvió JSON de la lista. Muchos paneles usan 401/403/511/512 para indicar «IP no permitida» o «credenciales incorrectas».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "El panel está accesible, pero rechazó las credenciales: usuario o contraseña incorrectos, suscripción caducada o demasiadas conexiones activas.",
    "The panel returned data this client could not parse.":
        "El panel devolvió datos que este cliente no podía analizar.",
    "The server address \"{server}\" is not a valid URL ({reason}).": "La dirección del servidor \"{server}\" no es una URL válida ({reason}).",
    "Theme": "Tema",
    "This series has no episodes listed.":
        "Esta serie no tiene episodios listados.",
