        "Se agotó el tiempo de espera al conectar con {server}",
    "Toggle list / grid": "Alternar entre lista y cuadrícula",
    "Toggle spacing": "Cambiar espaciado",
    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Se probaron {count} paneles. Comprueba el usuario y la contraseña, o añade la dirección del servidor del proveedor en Avanzado.",
    "Trying {panel} ({current}/{total})…":
        "Probando {panel} ({current}/{total})…",
    "Unexpected login response": "Respuesta de inicio de sesión inesperada",
