    "Use this server": "Usar este servidor",
    "Username": "Nombre de usuario",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Diagnóstico: {host} no respondió (ni en el puerto indicado, {port}, ni en los habituales). El servidor está desconectado, bloqueado por un cortafuegos o la dirección es incorrecta.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Diagnóstico: el host responde (HTTP {status}), pero no como panel Xtream. Suele deberse a un bloqueo por IP o red (401/403/511/512) o a un puerto incorrecto; consulta los detalles anteriores.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Diagnóstico: el panel responde en el puerto {port}, pero rechazó las credenciales: usuario o contraseña incorrectos, suscripción caducada o demasiadas conexiones.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Diagnóstico: {host} corresponde a una dirección de relleno (Cloudflare usa 1.1.1.1 / 1.0.0.1 cuando un registro DNS no apunta a ningún servidor). Ninguna solicitud puede llegar allí; el usuario y la contraseña ni siquiera se envían. Pide el host actual del panel a quien te dio la dirección. Si una aplicación anterior todavía permite iniciar sesión, utiliza otro host.",
    "View & refresh": "Ver y actualizar",
