  "fr": {
    "Account": "Compte",
    "Account & settings": "Compte et paramètres",
    "Account expired on {date}": "Compte expiré le {date}",
    "All": "Tous",
    "All titles": "Tous les titres",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Tout client compatible avec Xtream Codes peut utiliser ces liens. Ils contiennent votre nom d’utilisateur et votre mot de passe : gardez-les confidentiels et ne les publiez pas dans des discussions ou sur des sites publics.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Les flèches déplacent la sélection, Enter (ou OK sur la télécommande) valide et Esc/Back revient en arrière. Dans le lecteur, appuyez sur OK pour afficher les commandes, sélectionnez un bouton avec les flèches, puis validez avec OK. Lorsque la vidéo est sélectionnée, ↑↓ change de chaîne et ←→ avance ou recule, ou règle le volume du direct ; Enter/Space met en pause, M coupe le son et C active le mode cinéma. Les télécommandes Fire TV et Android TV et les contrôleurs émettant des touches clavier fonctionnent ; les manettes sans événements clavier ne sont pas encore prises en charge.",
    "Back": "Précédent",
    "Back 10 s (←)": "Reculer de 10 s (←)",
    "Back to sections": "Retour aux sections",
    "Big hero banner over per-category poster rails": "Grande bannière principale au-dessus des rangées d’affiches par catégorie",
