    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare ne peut pas joindre le serveur d’origine ({server}) : code d’erreur 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "L’erreur Cloudflare 1034 signifie que l’enregistrement DNS du domaine pointe vers une adresse fictive (par ex. 1.1.1.1). Aucune requête n’atteint donc le serveur. Aucun client ne peut se connecter tant que le fournisseur n’a pas corrigé cet enregistrement ; les identifiants ne sont pas en cause.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Erreur Cloudflare 1034 : l’enregistrement DNS pointe vers une adresse fictive sans serveur derrière",
