    "Tab strip and category rail on desktop, bottom nav on phones": "Onglets et catégories sur ordinateur ; barre de navigation en bas sur téléphone",
    "Test a list of servers": "Tester une liste de serveurs",
    "Test these servers": "Testez ces serveurs",
    "Testing…": "Test en cours…",
    "That address is a placeholder, not a server.":
        "Cette adresse est fictive, ce n’est pas un serveur.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Ce port utilise HTTP sans chiffrement, pas TLS : retirez https:// (les panneaux Xtream utilisent généralement http://host:8080). L’application réessaie déjà via http ; si ce message apparaît, cette tentative a également échoué.",
    "The account exists but its expiry date has passed.":
        "Le compte existe mais sa date d'expiration est passée.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "L’hôte n’a pas répondu. Causes fréquentes : nom d’hôte ou port incorrect, DNS mal configuré, pare-feu ou panneau inactif sur ce port.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Le nom d’hôte correspond à une adresse qui ne peut pas héberger de panneau (Cloudflare utilise 1.1.1.1 / 1.0.0.1 lorsqu’un enregistrement DNS ne pointe nulle part). Aucune donnée envoyée à cette adresse ne peut atteindre un serveur ; le nom d’utilisateur et le mot de passe ne sont donc même pas transmis. Demandez l’adresse actuelle à votre fournisseur ou collez sa liste d’hôtes dans « Tester une liste de serveurs ».",
    "The on-demand library": "La bibliothèque à la demande",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Le panneau a répondu avec HTTP {statusCode}, mais pas avec le JSON de la liste de lecture. De nombreux panneaux utilisent 401/403/511/512 pour signaler « IP non autorisée » ou « identifiants incorrects ».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Le panneau est accessible et a refusé ces identifiants : nom d'utilisateur/mot de passe erroné, abonnement expiré, ou trop de connexions utilisées.",
    "The panel returned data this client could not parse.":
        "Le panneau a renvoyé des données que ce client ne peut pas analyser.",
    "The server address \"{server}\" is not a valid URL ({reason}).": "L’adresse du serveur « {server} » n’est pas une URL valide ({reason}).",
    "Theme": "Thème",
    "This series has no episodes listed.":
        "Aucun épisode n’est répertorié pour cette série.",
    "Timed out talking to {server}": "Délai d’attente dépassé pour {server}",
    "Toggle list / grid": "Basculer entre liste et grille",
    "Toggle spacing": "Modifier l’espacement",
    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "{count} panneaux essayés. Vérifiez votre nom d’utilisateur et votre mot de passe, ou ajoutez l’adresse du fournisseur dans les options avancées.",
    "Trying {panel} ({current}/{total})…":
        "Essai de {panel} ({current}/{total})…",
    "Unexpected login response": "Réponse inattendue à la connexion",
    "Unknown": "Inconnu",
    "Unnamed": "Sans nom",
    "Use": "Utiliser",
    "Use the same subscription in another app":
        "Utilisez le même abonnement dans une autre application",
    "Use this server": "Utiliser ce serveur",
    "Username": "Nom d'utilisateur",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Diagnostic : aucune réponse de {host} (ni sur le port saisi {port}, ni sur les ports habituels). L’hôte est hors ligne, bloqué par un pare-feu ou l’adresse est erronée.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Diagnostic : l’hôte répond (HTTP {status}), mais pas comme un panneau Xtream. Il s’agit souvent d’un blocage IP/réseau (401/403/511/512) ou d’un mauvais port ; consultez les détails ci-dessus.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Diagnostic : le panneau répond sur le port {port}, mais refuse ces identifiants : nom d’utilisateur ou mot de passe incorrect, abonnement expiré ou trop de connexions.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Diagnostic : {host} correspond à une adresse fictive (Cloudflare utilise 1.1.1.1 / 1.0.0.1 lorsqu’un enregistrement DNS ne pointe nulle part). Aucune requête n’y atteint un serveur ; le nom d’utilisateur et le mot de passe ne sont donc pas envoyés. Demandez l’adresse actuelle du panneau à votre fournisseur. Si une ancienne application fonctionne encore, elle utilise un autre hôte.",
    "View & refresh": "Afficher et actualiser",
    "View, refresh & account": "Affichage, actualisation et compte",
    "Warm dark, gold and rose": "Noir chaud, or et rose",
