  "it": {
    "Account": "Account",
    "Account & settings": "Account e impostazioni",
    "Account expired on {date}": "Account scaduto il {date}",
    "All": "Tutti",
    "All titles": "Tutti i titoli",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Qualsiasi client compatibile con Xtream Codes può usare questi collegamenti. Contengono nome utente e password: trattali come dati riservati e non incollarli in chat o siti pubblici.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Le frecce spostano la selezione, Enter (o OK sul telecomando) conferma ed Esc/Back torna alla schermata precedente. Nel lettore, premi OK per mostrare i comandi, seleziona un pulsante con le frecce e premi OK per attivarlo. Quando il video è selezionato, ↑↓ cambia canale e ←→ scorre il video o regola il volume in diretta; Enter/Space mette in pausa, M disattiva l’audio e C attiva la modalità cinema. Funzionano i telecomandi Fire TV e Android TV e i controller che inviano comandi da tastiera; i gamepad senza eventi tastiera non sono ancora supportati.",
    "Back": "Indietro",
    "Back 10 s (←)": "Indietro 10 s (←)",
    "Back to sections": "Torna alle sezioni",
    "Big hero banner over per-category poster rails":
        "Grande banner principale sopra le file di locandine per categoria",
    "Browse": "Sfoglia",
    "Browse all": "Sfoglia tutto",
