    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare non riesce a raggiungere il server di origine ({server}): codice di errore 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "L’errore Cloudflare 1034 indica che il record DNS del dominio punta a un indirizzo segnaposto (ad es. 1.1.1.1), quindi nessuna richiesta raggiunge il server. Nessun client può accedere finché il provider non corregge il record; le credenziali non sono il problema.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Errore Cloudflare 1034: il record DNS punta a un indirizzo segnaposto senza un server dietro",
    "Comfortable": "Confortevole",
