    "Testing…": "Verifica in corso…",
    "That address is a placeholder, not a server.":
        "Questo indirizzo è un segnaposto, non un server.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Questa porta usa HTTP non cifrato, non TLS: rimuovi https:// (i pannelli Xtream usano di solito http://host:8080). L’app ritenta già tramite http; se vedi questo messaggio, anche quel tentativo è fallito.",
    "The account exists but its expiry date has passed.":
        "L’account esiste, ma è scaduto.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "L’host non ha risposto. Cause comuni: nome host o porta errati, DNS non valido, firewall oppure pannello non in ascolto su quella porta.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Il nome host corrisponde a un indirizzo che non può ospitare un pannello (Cloudflare usa 1.1.1.1 / 1.0.0.1 quando un record DNS non punta a nulla). Nessuna richiesta inviata lì può raggiungere un server, quindi nome utente e password non vengono nemmeno trasmessi. Chiedi a chi ti ha fornito l’indirizzo quello attuale, oppure incolla la sua lista di host in «Prova un elenco di server».",
    "The on-demand library": "La libreria on demand",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Il pannello ha risposto con HTTP {statusCode}, ma non con il JSON della playlist. Molti pannelli usano 401/403/511/512 per indicare «IP non consentito» o «credenziali errate».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Il pannello è raggiungibile, ma ha rifiutato le credenziali: nome utente o password errati, abbonamento scaduto o troppe connessioni attive.",
    "The panel returned data this client could not parse.": "Il pannello ha restituito dati che questo client non riesce ad analizzare.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "L'indirizzo server \"{server}\" non è un URL valido ({reason}).",
