    "Username": "Nome utente",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Diagnosi: nessuna risposta da {host} (né sulla porta indicata {port}, né sulle porte abituali). L’host è offline, bloccato da un firewall o l’indirizzo è errato.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Diagnosi: l’host risponde (HTTP {status}), ma non come pannello Xtream. Spesso si tratta di un blocco IP/rete (401/403/511/512) o di una porta errata; consulta i dettagli sopra.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Diagnosi: il pannello è raggiungibile sulla porta {port}, ma ha rifiutato le credenziali: nome utente o password errati, abbonamento scaduto o troppe connessioni.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Diagnosi: {host} corrisponde a un indirizzo segnaposto (Cloudflare usa 1.1.1.1 / 1.0.0.1 quando un record DNS non punta a nulla). Nessuna richiesta può raggiungere un server lì, quindi nome utente e password non vengono inviati. Chiedi l’host attuale a chi ti ha fornito l’indirizzo; se un’app precedente consente ancora l’accesso, usa un host diverso.",
