    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Qualquer cliente compatível com Xtream Codes pode usar esses links. Eles contêm seu nome de usuário e sua senha: trate-os como informação confidencial e não os cole em conversas ou sites públicos.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "As setas movem o foco, Enter (ou OK no controle remoto) confirma e Esc/Back retorna. No reprodutor, pressione OK para mostrar os controles; escolha um botão com as setas e pressione OK para ativá-lo. Com o vídeo em foco, ↑↓ muda de canal e ←→ avança ou retrocede, ou ajusta o volume da TV ao vivo; Enter/Space pausa, M silencia e C ativa o modo cinema. Controles remotos Fire TV e Android TV e dispositivos que enviam teclas funcionam; gamepads sem eventos de teclado ainda não são compatíveis.",
    "Back": "Voltar",
    "Back 10 s (←)": "Voltar 10 s (←)",
