    "Cloudflare could not reach the origin ({server}): error code 1034": "O Cloudflare não conseguiu alcançar o servidor de origem ({server}): código de erro 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "O erro 1034 do Cloudflare indica que o registro DNS do domínio aponta para um endereço provisório (por exemplo, 1.1.1.1). Assim, nenhuma solicitação chega ao servidor. Nenhum cliente consegue entrar até que o provedor corrija esse registro; as credenciais não são o problema.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Erro 1034 do Cloudflare: o registro DNS aponta para um endereço provisório sem servidor ativo",
