    "Test a list of servers": "Testar uma lista de servidores",
    "Test these servers": "Testar estes servidores",
    "Testing…": "Testando…",
    "That address is a placeholder, not a server.":
        "Este endereço é provisório, não é um servidor.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Essa porta usa HTTP sem criptografia, não TLS: remova https:// (painéis Xtream normalmente usam http://host:8080). O aplicativo já tenta novamente com http; se esta mensagem apareceu, essa tentativa também falhou.",
    "The account exists but its expiry date has passed.":
        "A conta existe, mas sua data de validade já passou.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "O host não respondeu. Causas comuns: nome do host ou porta incorretos, DNS mal configurado, firewall ou painel inativo nessa porta.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "O nome do host resolve para um endereço que não pode hospedar um painel (o Cloudflare usa 1.1.1.1 / 1.0.0.1 quando um registro DNS não aponta para lugar nenhum). Nenhuma solicitação enviada para lá consegue chegar a um servidor; portanto, o nome de usuário e a senha nem sequer são transmitidos. Peça o host atual a quem forneceu o endereço ou cole a lista de hosts em «Testar uma lista de servidores».",
    "The on-demand library": "A biblioteca sob demanda",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "O painel respondeu com HTTP {statusCode} mas não com a lista de reprodução JSON. Muitos painéis usam 401/403/511/512 para \"não permitido a partir deste IP\" ou \"más credenciais\".",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "O painel está acessível, mas recusou as credenciais: nome de usuário ou senha incorretos, assinatura expirada ou conexões ativas demais.",
    "The panel returned data this client could not parse.":
        "O painel retornou dados que este cliente não conseguiu analisar.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "O endereço do servidor \"{server}\" não é uma URL válida ({reason}).",
    "Theme": "Tema",
    "This series has no episodes listed.":
        "Esta série não tem episódios listados.",
