    "Toggle list / grid": "Alternar entre lista e grade",
    "Toggle spacing": "Alterar espaçamento",
    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Foram testados {count} painéis. Confira o nome de usuário e a senha ou adicione o endereço do servidor do provedor em Avançado.",
    "Trying {panel} ({current}/{total})…":
        "Tentando {panel} ({current}/{total})…",
