    "Use this server": "Usar este servidor",
    "Username": "Nome de usuário",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Diagnóstico: nenhuma resposta de {host} (nem na porta informada {port}, nem nas portas habituais). O host está offline, bloqueado por um firewall ou o endereço está incorreto.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Diagnóstico: o host responde (HTTP {status}), mas não como painel Xtream. Geralmente isso indica bloqueio por IP/rede (401/403/511/512) ou porta incorreta; veja os detalhes acima.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Diagnóstico: o painel responde na porta {port}, mas recusou as credenciais: nome de usuário ou senha incorretos, assinatura expirada ou conexões demais.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Diagnóstico: {host} resolve para um endereço provisório (o Cloudflare usa 1.1.1.1 / 1.0.0.1 quando um registro DNS não aponta para lugar nenhum). Nenhuma solicitação chega a um servidor nesse endereço; por isso, o nome de usuário e a senha não são enviados. Peça o host atual do painel a quem forneceu o endereço. Se outro aplicativo ainda permite entrar, ele usa um host diferente.",
