    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Elke app die Xtream Codes ondersteunt, kan deze links gebruiken. Ze bevatten je gebruikersnaam en wachtwoord. Behandel ze daarom als vertrouwelijk en deel ze niet in chats of op openbare websites.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Met de pijltjestoetsen verplaats je de focus; met Enter (of OK op de afstandsbediening) bevestig je; met Esc/Terug ga je terug. Druk in de speler op OK om de bediening te tonen. Kies met de pijlen een knop en bevestig met OK. Wanneer de video focus heeft, wissel je met ↑↓ van kanaal en spoel je met ←→ of pas je bij live-tv het volume aan. Enter/Spatie pauzeert, M dempt en C schakelt de bioscoopmodus in of uit. Fire TV- en Android TV-afstandsbedieningen en toetsenbordcontrollers werken; gamepads zonder toetsenbordinvoer worden nog niet ondersteund.",
