    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare-fout 1034 betekent dat het DNS-record van het domein naar een tijdelijk adres verwijst (bijv. 1.1.1.1). Daardoor bereikt geen enkel verzoek de server. Niemand kan inloggen totdat de aanbieder het record herstelt; je inloggegevens zijn niet het probleem.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Cloudflare-fout 1034 — het DNS-record verwijst naar een tijdelijk adres waarachter geen server bereikbaar is",
