    "Testing…": "Testen…",
    "That address is a placeholder, not a server.":
        "Dat adres is een tijdelijk adres, geen server.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Die poort gebruikt HTTP zonder TLS. Verwijder https:// (Xtream-panelen gebruiken meestal http://host:8080). De app heeft HTTP al geprobeerd; als je dit bericht ziet, is ook die poging mislukt.",
    "The account exists but its expiry date has passed.":
        "Het account bestaat, maar de vervaldatum is verstreken.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "De server reageert helemaal niet. Mogelijke oorzaken: een verkeerde hostnaam of poort, een onjuist DNS-record, een firewall of een paneel dat niet op deze poort luistert.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "De hostnaam verwijst naar een adres waarop geen paneel bereikbaar is (Cloudflare gebruikt 1.1.1.1 / 1.0.0.1 als een DNS-record nergens naartoe verwijst). Je gebruikersnaam en wachtwoord worden daarom niet verzonden. Vraag de aanbieder om het actuele serveradres of plak diens lijst met servers in 'Een lijst met servers testen'.",
    "The on-demand library": "De on-demandbibliotheek",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Het paneel antwoordde met HTTP {statusCode}, maar niet met afspeellijst-JSON. Veel panelen gebruiken 401/403/511/512 voor 'niet toegestaan vanaf dit IP-adres' of 'onjuiste inloggegevens'.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Het paneel is bereikbaar, maar heeft deze inloggegevens geweigerd: onjuiste gebruikersnaam of wachtwoord, een verlopen abonnement of te veel actieve verbindingen.",
    "The panel returned data this client could not parse.":
        "Het paneel stuurde gegevens terug die deze app niet kon verwerken.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Het serveradres '{server}' is geen geldige URL ({reason}).",
    "Theme": "Thema",
    "This series has no episodes listed.":
        "Voor deze serie staan geen afleveringen vermeld.",
    "Timed out talking to {server}": "Time-out bij verbinding met {server}",
    "Toggle list / grid": "Wisselen tussen lijst en raster",
    "Toggle spacing": "Tussenruimte wijzigen",
    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "{count} panelen geprobeerd. Controleer je gebruikersnaam en wachtwoord, of voeg onder Geavanceerd het serveradres van je aanbieder toe.",
    "Trying {panel} ({current}/{total})…":
        "{panel} proberen ({current}/{total})…",
    "Unexpected login response": "Onverwacht antwoord bij inloggen",
    "Unknown": "Onbekend",
