    "Use the same subscription in another app":
        "Hetzelfde abonnement in een andere app gebruiken",
    "Use this server": "Deze server gebruiken",
    "Username": "Gebruikersnaam",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Conclusie: {host} heeft niet gereageerd (op poort {port} en de gebruikelijke paneelpoorten). De server is offline, wordt geblokkeerd door een firewall of het adres klopt niet.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Conclusie: de server reageert (HTTP {status}), maar niet als Xtream-paneel. Meestal komt dit door een IP-/netwerkblokkade (401/403/511/512) of een verkeerde poort. Zie de details hierboven.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Conclusie: het paneel is bereikbaar op poort {port}, maar heeft deze inloggegevens geweigerd — door een onjuiste gebruikersnaam of wachtwoord, een verlopen abonnement of te veel verbindingen.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Conclusie: {host} verwijst naar een tijdelijk adres (Cloudflare gebruikt 1.1.1.1 / 1.0.0.1 als een DNS-record nergens naartoe verwijst). Geen enkel verzoek bereikt daar een server; je gebruikersnaam en wachtwoord worden niet verzonden. Vraag de aanbieder om het actuele paneeladres. Als een andere app nog wel kan inloggen, gebruikt die een andere server.",
    "View & refresh": "Weergave en vernieuwen",
    "View, refresh & account": "Weergave, vernieuwen en account",
