    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Każda aplikacja obsługująca Xtream Codes może używać tych linków. Zawierają nazwę użytkownika i hasło, więc traktuj je jak poufne dane. Nie wklejaj ich do czatów ani na publiczne strony.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Strzałki przenoszą zaznaczenie, Enter (lub OK na pilocie) zatwierdza, a Esc/Wstecz cofa. W odtwarzaczu naciśnij OK, aby pokazać elementy sterujące. Wybierz przycisk strzałkami i zatwierdź OK. Gdy zaznaczone jest wideo, ↑↓ zmieniają kanał, a ←→ przewijają lub regulują głośność telewizji na żywo. Enter/Spacja wstrzymuje, M wycisza, a C przełącza tryb kinowy. Działają piloty Fire TV i Android TV oraz kontrolery wysyłające zdarzenia klawiatury; zwykłe gamepady bez takich zdarzeń nie są jeszcze obsługiwane.",
    "Back": "Wstecz",
