    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare nie może połączyć się z serwerem źródłowym ({server}): kod błędu 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Błąd Cloudflare 1034 oznacza, że rekord DNS domeny wskazuje adres zastępczy (np. 1.1.1.1), więc żadne żądanie nie dociera do serwera. Logowanie nie zadziała, dopóki dostawca nie poprawi rekordu — dane logowania nie są problemem.",
