    "Only needed when a login fails and the address itself is in doubt. Nothing here is sent anywhere except the servers you name.": "Potrzebne tylko wtedy, gdy logowanie się nie powiedzie i adres budzi wątpliwości. Dane są wysyłane wyłącznie do wskazanych przez Ciebie serwerów.",
