    "Tab strip and category rail on desktop, bottom nav on phones":
        "Karty i lista kategorii na komputerze, dolna nawigacja na telefonie",
    "Test a list of servers": "Sprawdź listę serwerów",
    "Test these servers": "Sprawdź te serwery",
    "Testing…": "Sprawdzanie…",
    "That address is a placeholder, not a server.":
        "To adres zastępczy, a nie serwer.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Ten port obsługuje zwykły HTTP, a nie TLS — usuń https:// (panele Xtream zwykle działają pod http://host:8080). Aplikacja próbowała już połączenia przez HTTP; jeśli widzisz ten komunikat, ta próba również się nie powiodła.",
    "The account exists but its expiry date has passed.":
        "Konto istnieje, ale upłynął termin jego ważności.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Serwer w ogóle nie odpowiedział. Możliwe przyczyny: błędna nazwa hosta lub port, nieprawidłowy rekord DNS, zapora sieciowa albo panel nienasłuchujący na tym porcie.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Nazwa hosta wskazuje adres, pod którym nie może działać panel (Cloudflare używa 1.1.1.1 / 1.0.0.1, gdy rekord DNS nie wskazuje właściwego serwera). Dane wysyłane pod ten adres nie docierają do serwera, więc nazwa użytkownika i hasło w ogóle nie są przesyłane. Poproś dostawcę o aktualny adres serwera lub wklej jego listę adresów do „Sprawdź listę serwerów”.",
    "The on-demand library": "Biblioteka na żądanie",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Panel odpowiedział kodem HTTP {statusCode}, ale nie zwrócił danych listy odtwarzania w formacie JSON. Wiele paneli używa kodów 401/403/511/512, gdy dostęp z tego adresu IP jest zabroniony lub dane logowania są błędne.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Panel jest dostępny, ale odrzucił dane logowania: błędna nazwa użytkownika lub hasło, wygasła subskrypcja albo zbyt wiele aktywnych połączeń.",
    "The panel returned data this client could not parse.":
        "Panel zwrócił dane, których aplikacja nie mogła przetworzyć.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Adres serwera „{server}” nie jest poprawnym URL-em ({reason}).",
