    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Sprawdzono {count} paneli. Zweryfikuj nazwę użytkownika i hasło albo dodaj adres serwera dostawcy w sekcji Zaawansowane.",
    "Trying {panel} ({current}/{total})…":
