    "Use this server": "Użyj tego serwera",
    "Username": "Nazwa użytkownika",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Wynik: {host} nie odpowiedział (na podanym porcie {port} ani na typowych portach panelu). Serwer może być offline, blokowany przez zaporę lub adres może być błędny.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Wynik: serwer odpowiada (HTTP {status}), ale nie jako panel Xtream. Zwykle oznacza to blokadę IP/sieci (401/403/511/512) lub błędny port — szczegóły znajdziesz powyżej.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Wynik: panel jest dostępny na porcie {port}, ale odrzucił dane logowania — możliwe przyczyny to błędna nazwa użytkownika lub hasło, wygasła subskrypcja albo zbyt wiele połączeń.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Wynik: {host} wskazuje adres zastępczy (Cloudflare używa 1.1.1.1 / 1.0.0.1, gdy rekord DNS nie wskazuje właściwego serwera). Żadne żądanie nie dociera tam do serwera, więc nazwa użytkownika i hasło nie są wysyłane. Poproś dostawcę o aktualny adres panelu. Jeśli inna aplikacja nadal pozwala się zalogować, korzysta z innego serwera.",
    "View & refresh": "Widok i odświeżanie",
