  "cs": {
    "Account": "Účet",
    "Account & settings": "Účet a nastavení",
    "Account expired on {date}": "Platnost účtu skončila {date}",
    "All": "Vše",
    "All titles": "Všechny tituly",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Tyto odkazy může použít každá aplikace podporující Xtream Codes. Obsahují vaše uživatelské jméno a heslo, proto je považujte za důvěrné a nesdílejte je v chatech ani na veřejných webech.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Šipkami přesunete výběr, Enter (nebo OK na ovladači) potvrdí volbu a Esc/Zpět vás vrátí zpět. V přehrávači zobrazíte ovládání tlačítkem OK. Šipkami vyberte tlačítko a potvrďte je tlačítkem OK. Když je vybrané video, ↑↓ přepínají kanály a ←→ posouvají přehrávání nebo mění hlasitost živého vysílání. Enter/Mezerník pozastaví přehrávání, M ztlumí zvuk a C přepne režim kina. Fungují ovladače Fire TV a Android TV i zařízení vysílající klávesové události; běžné gamepady bez nich zatím nejsou podporovány.",
    "Back": "Zpět",
    "Back 10 s (←)": "Zpět o 10 s (←)",
    "Back to sections": "Zpět k sekcím",
    "Big hero banner over per-category poster rails":
        "Velký úvodní banner nad řadami plakátů jednotlivých kategorií",
    "Browse": "Procházet",
    "Browse all": "Procházet vše",
    "Cannot reach {server}: {reason}": "Nelze se připojit k {server}: {reason}",
