        "Kategorie vlevo, obsah vpravo",
    "Channels, movies, series": "Kanály, filmy a seriály",
    "Channels, now and next": "Kanály, právě vysílané a následující pořady",
    "Check without a login": "Ověřit bez přihlášení",
