    "Checking…": "Kontrola…",
    "Cinema": "Režim kina",
    "Cinema (C)": "Režim kina (C)",
    "Classic": "Klasický",
    "Clear search": "Vymazat hledání",
    "Close": "Zavřít",
    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare se nemohl připojit k původnímu serveru ({server}): kód chyby 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Chyba Cloudflare 1034 znamená, že záznam DNS domény ukazuje na zástupnou adresu (např. 1.1.1.1), takže žádný požadavek nedorazí na server. Přihlášení nebude fungovat, dokud poskytovatel záznam neopraví — problém není v přihlašovacích údajích.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Chyba Cloudflare 1034 — záznam DNS ukazuje na zástupnou adresu, za níž není dostupný server",
    "Comfortable": "Pohodlný",
    "Comfortable spacing": "Větší rozestupy",
    "Compact": "Kompaktní",
    "Compact section tiles with artwork and a remote-friendly focus path":
        "Kompaktní dlaždice sekcí s obrázky a snadným ovládáním ovladačem",
    "Compact spacing": "Menší rozestupy",
    "Compact spacing (fits more)": "Menší rozestupy (více na obrazovce)",
    "Connections": "Připojení",
    "Could not load episodes. Check your connection and retry.": "Epizody se nepodařilo načíst. Zkontrolujte připojení a zkuste to znovu.",
