    "Test a list of servers": "Otestovat seznam serverů",
    "Test these servers": "Otestovat tyto servery",
    "Testing…": "Testování…",
    "That address is a placeholder, not a server.":
        "Tato adresa je zástupná, nepatří serveru.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Tento port používá běžné HTTP, nikoli TLS — odstraňte https:// (panely Xtream obvykle fungují na http://host:8080). Aplikace již zkusila připojení přes HTTP; pokud vidíte tuto zprávu, ani tento pokus nevyšel.",
    "The account exists but its expiry date has passed.":
        "Účet existuje, ale jeho platnost již skončila.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Server vůbec neodpověděl. Možné příčiny: chybný název hostitele nebo port, nesprávný záznam DNS, firewall nebo panel nenaslouchá na daném portu.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Název hostitele ukazuje na adresu, na níž nemůže běžet panel (Cloudflare používá 1.1.1.1 / 1.0.0.1, když záznam DNS neukazuje na platný server). Nic odeslaného na tuto adresu se nedostane na server, takže uživatelské jméno a heslo se vůbec nepřenášejí. Požádejte poskytovatele o aktuální adresu serveru nebo jeho seznam adres vložte do „Otestovat seznam serverů“.",
    "The on-demand library": "Knihovna obsahu na vyžádání",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Panel odpověděl kódem HTTP {statusCode}, ale nevrátil data seznamu videí ve formátu JSON. Kódy 401/403/511/512 často znamenají zákaz přístupu z této IP adresy nebo chybné přihlašovací údaje.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Panel je dostupný, ale odmítl přihlašovací údaje: chybné uživatelské jméno nebo heslo, vypršelé předplatné či příliš mnoho aktivních připojení.",
    "The panel returned data this client could not parse.":
        "Panel vrátil data, která aplikace nedokázala zpracovat.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
