    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Vyzkoušeno {count} panelů. Zkontrolujte uživatelské jméno a heslo nebo přidejte adresu serveru poskytovatele v Pokročilých nastaveních.",
