    "Use this server": "Použít tento server",
    "Username": "Uživatelské jméno",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Výsledek: {host} neodpověděl (na zadaném portu {port} ani na obvyklých portech panelu). Server může být offline, blokovaný firewallem nebo adresa nesprávná.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Výsledek: server odpovídá (HTTP {status}), ale ne jako panel Xtream. Příčinou bývá blokování IP/sítě (401/403/511/512) nebo nesprávný port — podrobnosti najdete výše.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Výsledek: panel je dostupný na portu {port}, ale odmítl přihlašovací údaje — možnými příčinami jsou chybné uživatelské jméno nebo heslo, vypršelé předplatné nebo příliš mnoho připojení.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Výsledek: {host} ukazuje na zástupnou adresu (Cloudflare používá 1.1.1.1 / 1.0.0.1, když záznam DNS neukazuje na platný server). Žádný požadavek se tam nedostane na server, proto se uživatelské jméno ani heslo neodesílají. Požádejte poskytovatele o aktuální adresu panelu. Pokud se jiná aplikace stále přihlašuje, používá jiný server.",
