  "ru": {
    "Account": "Учётная запись",
    "Account & settings": "Учётная запись и настройки",
    "Account expired on {date}": "Срок действия учётной записи истёк {date}",
    "All": "Все",
    "All titles": "Все названия",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Эти ссылки можно использовать в любом клиенте Xtream Codes. Они содержат ваше имя пользователя и пароль: храните их в тайне и не публикуйте в чатах и на общедоступных сайтах.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Стрелки перемещают фокус, Enter (или OK на пульте) подтверждает выбор, Esc/Back возвращает назад. В плеере нажмите OK, чтобы показать элементы управления, затем выберите кнопку стрелками и нажмите OK. Когда фокус на видео, ↑↓ переключают каналы, ←→ перематывают или меняют громкость прямого эфира; Enter/Space ставят на паузу, M отключает звук, C переключает кинорежим. Пульты Fire TV / Android TV и контроллеры, передающие нажатия клавиш, поддерживаются; обычные геймпады без событий клавиатуры пока не назначены.",
    "Back": "Назад",
    "Back 10 s (←)": "Назад на 10 с (←)",
    "Back to sections": "К разделам",
    "Big hero banner over per-category poster rails":
        "Большой баннер над рядами постеров по категориям",
    "Browse": "Обзор",
