    "Close": "Закрыть",
    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare не смог подключиться к исходному серверу ({server}): код ошибки 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Ошибка Cloudflare 1034 означает, что DNS-запись домена указывает на адрес-заглушку (например, 1.1.1.1), поэтому запросы не доходят до сервера. Войти не удастся ни в одном клиенте, пока провайдер не исправит запись. Дело не в учётных данных.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Ошибка Cloudflare 1034 — DNS-запись указывает на заглушку, за которой нет сервера",
    "Comfortable": "Свободный",
