    "Test a list of servers": "Проверить список серверов",
    "Test these servers": "Проверить эти серверы",
    "Testing…": "Проверка…",
    "That address is a placeholder, not a server.":
        "Этот адрес — заглушка, а не сервер.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Этот порт использует обычный HTTP, а не TLS — уберите https:// (панели Xtream обычно доступны по http://host:8080). Приложение уже повторило запрос по http, поэтому если вы видите это сообщение, попытка по http тоже не удалась.",
    "The account exists but its expiry date has passed.":
        "Учётная запись существует, но срок её действия истёк.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Сервер не ответил. Возможные причины: неверное имя хоста или порт, недействующая DNS-запись, брандмауэр или отсутствие службы на этом порту.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Имя хоста указывает на адрес, по которому панель недоступна (Cloudflare использует 1.1.1.1 / 1.0.0.1 для DNS-записей без действующего сервера). Запросы не доходят до сервера, поэтому имя пользователя и пароль даже не передаются. Попросите актуальный адрес у того, кто его предоставил, или вставьте список хостов в поле «Проверить список серверов».",
    "The on-demand library": "Библиотека по запросу",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Панель ответила HTTP {statusCode}, но не вернула JSON плейлиста. Многие панели используют коды 401/403/511/512 для ошибок «доступ с этого IP запрещён» или «неверные учётные данные».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Панель доступна, но отклонила учётные данные: неверные имя пользователя или пароль, истёкшая подписка либо превышено число подключений.",
    "The panel returned data this client could not parse.":
        "Панель вернула данные, которые клиент не смог обработать.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Адрес сервера «{server}» не является допустимым URL ({reason}).",
    "Theme": "Тема",
    "This series has no episodes listed.":
        "Для этого сериала не указаны серии.",
