    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Проверено панелей: {count}. Проверьте имя пользователя и пароль или добавьте адрес сервера провайдера в разделе «Дополнительно».",
    "Trying {panel} ({current}/{total})…":
