        "Использовать подписку в другом приложении",
    "Use this server": "Использовать этот сервер",
    "Username": "Имя пользователя",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Результат: {host} не ответил (проверены указанный порт {port} и стандартные порты панелей). Сервер отключён, заблокирован брандмауэром или адрес неверен.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Результат: хост отвечает (HTTP {status}), но это не панель Xtream. Обычно причина — ограничение доступа по IP/сети (401/403/511/512) или неверный порт; подробности указаны выше.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Результат: панель доступна через порт {port}, но отклонила учётные данные — неверные имя пользователя или пароль, истёкшая подписка либо слишком много подключений.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Результат: {host} указывает на адрес-заглушку (Cloudflare использует 1.1.1.1 / 1.0.0.1, если DNS-запись никуда не ведёт). Запросы не доходят до сервера, поэтому имя пользователя и пароль даже не отправляются. Попросите у того, кто дал вам адрес, актуальный хост панели. Если другое приложение всё ещё выполняет вход, оно подключается к другому хосту.",
