  "uk": {
    "Account": "Обліковий запис",
    "Account & settings": "Обліковий запис і налаштування",
    "Account expired on {date}":
        "Термін дії облікового запису закінчився {date}",
    "All": "Усі",
    "All titles": "Усі назви",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Ці посилання можна використовувати в будь-якому клієнті Xtream Codes. Вони містять ваше ім’я користувача та пароль: зберігайте їх у таємниці й не публікуйте в чатах чи на загальнодоступних сайтах.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Стрілки переміщують фокус, Enter (або OK на пульті) підтверджує вибір, Esc/Back повертає назад. У програвачі натисніть OK, щоб показати елементи керування, потім виберіть кнопку стрілками й натисніть OK. Коли фокус на відео, ↑↓ перемикають канали, ←→ перемотують або змінюють гучність прямого ефіру; Enter/Space призупиняють відтворення, M вимикає звук, C перемикає кінорежим. Пульти Fire TV / Android TV і контролери, що передають натискання клавіш, підтримуються; звичайні геймпади без подій клавіатури поки не налаштовані.",
    "Back": "Назад",
    "Back 10 s (←)": "Назад на 10 с (←)",
    "Back to sections": "До розділів",
    "Big hero banner over per-category poster rails":
        "Великий банер над рядами постерів за категоріями",
    "Browse": "Перегляд",
    "Browse all": "Переглянути все",
    "Cannot reach {server}: {reason}":
        "Не вдається підключитися до {server}: {reason}",
    "Category column on the left, content on the right":
