    "Cinema (C)": "Кінорежим (C)",
    "Classic": "Класичний",
    "Clear search": "Очистити пошук",
    "Close": "Закрити",
    "Cloudflare could not reach the origin ({server}): error code 1034": "Cloudflare не зміг підключитися до вихідного сервера ({server}): код помилки 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Помилка Cloudflare 1034 означає, що DNS-запис домену вказує на адресу-заглушку (наприклад, 1.1.1.1), тому запити не доходять до сервера. Жоден клієнт не зможе ввійти, доки провайдер не виправить запис. Річ не в облікових даних.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Помилка Cloudflare 1034 — DNS-запис вказує на заглушку, за якою немає сервера",
    "Comfortable": "Просторий",
    "Comfortable spacing": "Просторі відступи",
    "Compact": "Компактний",
    "Compact section tiles with artwork and a remote-friendly focus path": "Компактні плитки розділів із зображеннями та зручною навігацією з пульта",
