    "OPEN — {live} live / {vod} VOD / {series} series categories without login": "ВІДКРИТО — {live} категорій прямого ефіру / {vod} VOD / {series} серіалів без входу",
    "On now": "Зараз в ефірі",
    "Only needed when a login fails and the address itself is in doubt. Nothing here is sent anywhere except the servers you name.": "Потрібно лише за невдалого входу, якщо є сумніви щодо адреси. Дані надсилаються тільки на вказані вами сервери.",
