    "Testing…": "Перевірка…",
    "That address is a placeholder, not a server.":
        "Ця адреса — заглушка, а не сервер.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Цей порт використовує звичайний HTTP, а не TLS — приберіть https:// (панелі Xtream зазвичай доступні за http://host:8080). Застосунок уже повторив запит через http, тому якщо ви бачите це повідомлення, спроба через http теж не вдалася.",
    "The account exists but its expiry date has passed.":
        "Обліковий запис існує, але термін його дії минув.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Сервер не відповів. Можливі причини: неправильне ім’я хоста чи порт, недійсний DNS-запис, брандмауер або відсутність служби на цьому порту.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Ім’я хоста вказує на адресу, за якою панель недоступна (Cloudflare використовує 1.1.1.1 / 1.0.0.1 для DNS-записів без чинного сервера). Запити не доходять до сервера, тому ім’я користувача й пароль навіть не передаються. Попросіть актуальну адресу в того, хто її надав, або вставте список хостів у поле «Перевірити список серверів».",
    "The on-demand library": "Бібліотека на вимогу",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Панель відповіла HTTP {statusCode}, але не повернула JSON плейлиста. Багато панелей використовують коди 401/403/511/512 для помилок «доступ із цього IP заборонено» або «неправильні облікові дані».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Панель доступна, але відхилила облікові дані: неправильне ім’я користувача чи пароль, прострочена підписка або перевищено кількість підключень.",
    "The panel returned data this client could not parse.":
        "Панель повернула дані, які клієнт не зміг обробити.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
