    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Перевірено панелей: {count}. Перевірте ім’я користувача й пароль або додайте адресу сервера провайдера в розділі «Додатково».",
    "Trying {panel} ({current}/{total})…":
