    "Username": "Ім’я користувача",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Результат: {host} не відповів (перевірено вказаний порт {port} і стандартні порти панелей). Сервер вимкнений, заблокований брандмауером або адреса неправильна.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Результат: хост відповідає (HTTP {status}), але це не панель Xtream. Зазвичай причина — обмеження доступу за IP/мережею (401/403/511/512) або неправильний порт; подробиці наведено вище.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Результат: панель доступна через порт {port}, але відхилила облікові дані — неправильне ім’я користувача чи пароль, прострочена підписка або забагато підключень.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Результат: {host} вказує на адресу-заглушку (Cloudflare використовує 1.1.1.1 / 1.0.0.1, якщо DNS-запис нікуди не веде). Запити не доходять до сервера, тому ім’я користувача й пароль навіть не надсилаються. Попросіть у того, хто дав вам адресу, актуальний хост панелі. Якщо інший застосунок досі виконує вхід, він підключається до іншого хоста.",
