  "tr": {
    "Account": "Hesap",
    "Account & settings": "Hesap ve ayarlar",
    "Account expired on {date}": "Hesabın süresi {date} tarihinde doldu",
    "All": "Tümü",
    "All titles": "Tüm içerikler",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Bu bağlantılar, Xtream Codes destekleyen tüm istemcilerde kullanılabilir. Kullanıcı adınızı ve parolanızı içerirler; bunları gizli tutun, sohbetlerde veya herkese açık sitelerde paylaşmayın.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Ok tuşları odağı taşır; Enter (veya kumandadaki OK) seçimi etkinleştirir, Esc/Back geri döner. Oynatıcıda kontrolleri göstermek için OK’ye basın, ardından oklarla bir düğme seçip OK’ye basın. Odak videodayken ↑↓ kanalları değiştirir, ←→ ileri/geri sarar veya canlı yayının ses düzeyini ayarlar; Enter/Space duraklatır, M sesi kapatır, C sinema modunu açar veya kapatır. Fire TV / Android TV kumandaları ve klavye tuşları gönderen kontrol cihazları çalışır; klavye olayı göndermeyen oyun kumandaları henüz eşlenmedi.",
    "Back": "Geri",
    "Back 10 s (←)": "10 sn geri (←)",
    "Back to sections": "Bölümlere dön",
    "Big hero banner over per-category poster rails":
        "Kategori afişlerinin üzerinde büyük öne çıkan görsel",
    "Browse": "Göz at",
    "Browse all": "Tümüne göz at",
