        "{server} sunucusuna ulaşılamıyor: {reason}",
    "Category column on the left, content on the right":
        "Solda kategori sütunu, sağda içerik",
    "Channels, movies, series": "Kanallar, filmler, diziler",
    "Channels, now and next": "Kanallar: şimdi ve sırada",
    "Check without a login": "Giriş yapmadan kontrol et",
    "Checking panels…": "Paneller kontrol ediliyor…",
    "Checking…": "Kontrol ediliyor…",
    "Cinema": "Sinema modu",
