    "Classic": "Klasik",
    "Clear search": "Aramayı temizle",
    "Close": "Kapat",
    "Cloudflare could not reach the origin ({server}): error code 1034":
        "Cloudflare kaynak sunucuya ({server}) ulaşamadı: hata kodu 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare 1034 hatası, alan adının DNS kaydının yer tutucu bir adrese (örneğin 1.1.1.1) işaret ettiği ve isteklerin sunucuya ulaşmadığı anlamına gelir. Sağlayıcı bu kaydı düzeltmeden hiçbir istemci giriş yapamaz. Sorun giriş bilgilerinde değildir.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Cloudflare 1034 hatası — DNS kaydı yer tutucu bir adrese işaret ediyor; arkasında çalışan bir sunucu yok",
