    "Tab strip and category rail on desktop, bottom nav on phones":
        "Masaüstünde sekmeler ve kategoriler, telefonlarda alt gezinme çubuğu",
    "Test a list of servers": "Sunucu listesini kontrol et",
    "Test these servers": "Bu sunucuları kontrol et",
    "Testing…": "Kontrol ediliyor…",
    "That address is a placeholder, not a server.":
        "Bu adres bir sunucu değil, yer tutucu.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Bu port TLS değil, düz HTTP kullanıyor — https:// yerine http:// kullanın (Xtream panelleri genellikle http://host:8080 adresindedir). Uygulama http üzerinden zaten yeniden denedi; bu mesajı görüyorsanız http denemesi de başarısız oldu.",
    "The account exists but its expiry date has passed.":
        "Hesap mevcut ancak süresi dolmuş.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Sunucu hiç yanıt vermedi. Olası nedenler: yanlış ana bilgisayar adı veya port, geçersiz bir adrese işaret eden DNS kaydı, güvenlik duvarı ya da panelin o portta çalışmaması.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Ana bilgisayar adı, panelin çalışamayacağı bir adrese çözülüyor (Cloudflare, DNS kaydı bir sunucuya işaret etmediğinde 1.1.1.1 / 1.0.0.1 kullanır). İstekler sunucuya ulaşmadığından kullanıcı adı ve parola iletilmez. Adresi sağlayan kişiden güncel sunucu adını isteyin veya sunucu listesini “Sunucu listesini kontrol et” alanına yapıştırın.",
    "The on-demand library": "İsteğe bağlı içerik kitaplığı",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Panel HTTP {statusCode} yanıtı verdi ancak çalma listesi JSON’unu döndürmedi. Birçok panel, “bu IP’den erişim yasak” veya “hatalı giriş bilgileri” için 401/403/511/512 kodlarını kullanır.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Panele erişilebiliyor ancak giriş bilgileri reddedildi: kullanıcı adı veya parola yanlış, aboneliğin süresi dolmuş ya da çok fazla bağlantı kullanılıyor.",
    "The panel returned data this client could not parse.":
        "Panel, bu istemcinin işleyemediği veriler döndürdü.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
