    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "{count} panel denendi. Kullanıcı adını ve parolayı kontrol edin veya sağlayıcının sunucu adresini Gelişmiş bölümüne ekleyin.",
