    "Use this server": "Bu sunucuyu kullan",
    "Username": "Kullanıcı adı",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Sonuç: {host} yanıt vermedi (girilen port {port} ve yaygın panel portları kontrol edildi). Sunucu çevrimdışı, güvenlik duvarı tarafından engelleniyor veya adres yanlış.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Sonuç: sunucu yanıt veriyor (HTTP {status}) ancak Xtream paneli olarak değil. Bunun nedeni genellikle IP/ağ erişim kısıtlaması (401/403/511/512) veya yanlış porttur; ayrıntılar yukarıdadır.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Sonuç: panele {port} portundan erişiliyor ancak giriş bilgileri reddedildi — kullanıcı adı veya parola yanlış, aboneliğin süresi dolmuş ya da çok fazla bağlantı var.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Sonuç: {host} yer tutucu bir adrese çözülüyor (Cloudflare, DNS kaydı herhangi bir sunucuya işaret etmediğinde 1.1.1.1 / 1.0.0.1 kullanır). İstekler sunucuya ulaşmadığından kullanıcı adı ve parola gönderilmez. Adresi veren kişiden güncel panel sunucusunu isteyin. Daha önce kullandığınız bir uygulama hâlâ giriş yapabiliyorsa farklı bir sunucuya bağlanıyordur.",
    "View & refresh": "Görünüm ve yenileme",
