  "ar": {
    "Account": "الحساب",
    "Account & settings": "الحساب والإعدادات",
    "Account expired on {date}": "انتهت صلاحية الحساب في {date}",
    "All": "الكل",
    "All titles": "جميع العناوين",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "يمكن لأي تطبيق يدعم Xtream Codes استخدام هذه الروابط. تحتوي على اسم المستخدم وكلمة المرور، لذا تعامل معها كبيانات سرية ولا تلصقها في المحادثات أو المواقع العامة.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "تنقل الأسهم بين العناصر، ويُفعّل Enter (أو زر OK في جهاز التحكم) العنصر المحدد، ويعود Esc/Back للخلف. في المشغل، اضغط OK لإظهار عناصر التحكم، ثم اختر زرًا بالأسهم واضغط OK لتفعيله. عند تحديد الفيديو، يبدّل ↑↓ القناة، ويتيح ←→ التقديم أو تغيير مستوى الصوت للبث المباشر؛ يوقف Enter/Space التشغيل مؤقتًا، ويكتم M الصوت، ويبدّل C وضع السينما. تعمل أجهزة تحكم Fire TV وAndroid TV ولوحات المفاتيح؛ أما أذرع الألعاب التي لا ترسل ضغطات لوحة مفاتيح فلم تُدعَم بعد.",
    "Back": "العودة",
    "Back 10 s (←)": "الرجوع 10 ثوانٍ (←)",
    "Back to sections": "العودة إلى الأقسام",
    "Big hero banner over per-category poster rails":
        "لافتة رئيسية كبيرة فوق صفوف ملصقات لكل فئة",
