    "Cinema (C)": "وضع السينما (C)",
    "Classic": "كلاسيكي",
    "Clear search": "مسح البحث",
    "Close": "إغلاق",
    "Cloudflare could not reach the origin ({server}): error code 1034": "تعذّر على Cloudflare الوصول إلى الخادم الأصلي ({server}): رمز الخطأ 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "يعني خطأ Cloudflare رقم 1034 أن سجل DNS للنطاق يشير إلى عنوان مؤقت (مثل 1.1.1.1)، فلا تصل الطلبات إلى أي خادم. لن يتمكن أي تطبيق من تسجيل الدخول حتى يصلح المزوّد السجل؛ بيانات الدخول ليست المشكلة.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "خطأ Cloudflare رقم 1034 — يشير سجل DNS إلى عنوان مؤقت لا يوجد خلفه خادم",
    "Comfortable": "مريح",
    "Comfortable spacing": "التباعد المريح",
    "Compact": "مضغوط",
    "Compact section tiles with artwork and a remote-friendly focus path":
