    "Testing…": "جارٍ الفحص…",
    "That address is a placeholder, not a server.":
        "هذا عنوان مؤقت، وليس عنوان خادم.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "يستخدم هذا المنفذ HTTP العادي لا TLS؛ احذف https:// (تعمل لوحات Xtream عادةً عبر http://host:8080). حاول التطبيق بالفعل الاتصال عبر http، لذا فإن ظهور هذه الرسالة يعني فشل تلك المحاولة أيضًا.",
    "The account exists but its expiry date has passed.":
        "الحساب موجود لكن صلاحيته انتهت.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "لم يستجب المضيف مطلقًا. من الأسباب المعتادة: خطأ في اسم المضيف أو المنفذ، أو سجل DNS يشير إلى عنوان غير صالح، أو جدار حماية، أو أن اللوحة لا تستمع على ذلك المنفذ.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "يشير اسم المضيف إلى عنوان لا يمكنه تشغيل لوحة (تستخدم Cloudflare العنوانين 1.1.1.1 و 1.0.0.1  عندما لا يشير سجل DNS إلى خادم). لن يصل ما يُرسل إليه إلى أي خادم، لذا لا يُرسل اسم المستخدم وكلمة المرور أصلًا. اطلب العنوان الحالي ممن زوّدك به، أو الصق قائمة المضيفين في «فحص قائمة خوادم».",
    "The on-demand library": "مكتبة المشاهدة حسب الطلب",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "ردّت اللوحة برمز HTTP {statusCode} ولكن ليس ببيانات قائمة تشغيل بتنسيق JSON. تستخدم لوحات كثيرة الرموز 401/403/511/512 للدلالة على «هذا العنوان IP غير مسموح» أو «بيانات الدخول غير صحيحة».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "يمكن الوصول إلى اللوحة لكنها رفضت بيانات الدخول: قد يكون اسم المستخدم أو كلمة المرور غير صحيحين، أو انتهى الاشتراك، أو بلغ عدد الاتصالات الحد الأقصى.",
    "The panel returned data this client could not parse.":
        "أعادت اللوحة بيانات تعذّر على التطبيق تحليلها.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "عنوان الخادم «{server}» ليس رابطًا صالحًا ({reason}).",
    "Theme": "المظهر",
