    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "جرت تجربة {count} لوحات. تحقق من اسم المستخدم وكلمة المرور، أو أضف عنوان خادم المزوّد ضمن الإعدادات المتقدمة.",
    "Trying {panel} ({current}/{total})…":
