    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "النتيجة: لم يستجب {host} على المنفذ المدخل {port} أو منافذ اللوحات المعتادة. قد يكون المضيف غير متصل أو محجوبًا بجدار حماية، أو العنوان غير صحيح.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "النتيجة: يستجيب المضيف (HTTP {status}) لكن ليس بوصفه لوحة Xtream. غالبًا بسبب حظر عنوان IP أو الشبكة (401/403/511/512) أو خطأ في المنفذ؛ راجع التفاصيل أعلاه.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "النتيجة: يمكن الوصول إلى اللوحة على المنفذ {port} لكنها رفضت بيانات الدخول، بسبب خطأ في اسم المستخدم أو كلمة المرور، أو انتهاء الاشتراك، أو كثرة الاتصالات.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "النتيجة: يشير {host} إلى عنوان مؤقت (تستخدم Cloudflare العنوانين 1.1.1.1 و 1.0.0.1  عندما لا يشير سجل DNS إلى خادم). لا تصل أي طلبات إلى خادم هناك، فلا يُرسل اسم المستخدم وكلمة المرور. اطلب ممن أعطاك العنوان مضيف اللوحة الحالي؛ إذا كان تطبيق استخدمته سابقًا لا يزال يسجّل الدخول، فهو يتصل بمضيف مختلف.",
