  "hi": {
    "Account": "खाता",
    "Account & settings": "खाता और सेटिंग",
    "Account expired on {date}": "खाते की अवधि {date} को समाप्त हुई",
    "All": "सभी",
    "All titles": "सभी शीर्षक",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Xtream Codes समर्थित कोई भी ऐप इन लिंक का उपयोग कर सकता है। इनमें आपका उपयोगकर्ता नाम और पासवर्ड शामिल हैं। इन्हें गोपनीय रखें और चैट या सार्वजनिक वेबसाइटों पर न डालें।",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "तीर कुंजियों से चयन बदलें, Enter (या रिमोट का OK) दबाकर चुनें और Esc/Back से वापस जाएँ। प्लेयर में नियंत्रण दिखाने के लिए OK दबाएँ, फिर तीर कुंजियों से बटन चुनकर OK दबाएँ। वीडियो चयनित होने पर ↑↓ से चैनल बदलें और ←→ से आगे-पीछे जाएँ या लाइव प्रसारण का वॉल्यूम बदलें; Enter/Space से रोकें, M से आवाज़ बंद करें और C से सिनेमा मोड बदलें। Fire TV और Android TV रिमोट तथा कीबोर्ड जैसे कंट्रोलर काम करते हैं; बिना कीबोर्ड सिग्नल वाले गेमपैड अभी समर्थित नहीं हैं।",
    "Back": "वापस",
