    "Cloudflare could not reach the origin ({server}): error code 1034":
        "Cloudflare मूल सर्वर ({server}) तक नहीं पहुँच सका: त्रुटि कोड 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare त्रुटि 1034 का अर्थ है कि डोमेन का DNS रिकॉर्ड किसी अस्थायी पते (जैसे 1.1.1.1) की ओर इशारा कर रहा है, इसलिए अनुरोध सर्वर तक नहीं पहुँचते। प्रदाता के रिकॉर्ड ठीक करने तक कोई ऐप लॉग इन नहीं कर सकता; लॉगिन विवरण समस्या नहीं हैं।",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Cloudflare त्रुटि 1034 — DNS रिकॉर्ड अस्थायी पते की ओर इशारा करता है; वहाँ कोई सर्वर नहीं है",
