    "Testing…": "जाँच जारी है…",
    "That address is a placeholder, not a server.":
        "यह अस्थायी पता है, सर्वर नहीं।",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "यह पोर्ट TLS के बजाय सामान्य HTTP इस्तेमाल करता है — https:// हटाएँ (Xtream पैनल आम तौर पर http://host:8080 पर होते हैं)। ऐप पहले ही http पर दोबारा कोशिश कर चुका है; यह संदेश आने का मतलब वह कोशिश भी विफल रही।",
    "The account exists but its expiry date has passed.":
        "खाता मौजूद है, लेकिन इसकी अवधि समाप्त हो चुकी है।",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "सर्वर ने कोई जवाब नहीं दिया। सामान्य कारण: गलत होस्टनाम या पोर्ट, DNS का निष्क्रिय पते की ओर इशारा करना, फ़ायरवॉल या उस पोर्ट पर पैनल का उपलब्ध न होना।",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "होस्टनाम ऐसे पते की ओर इशारा करता है जहाँ पैनल नहीं चल सकता (जब DNS रिकॉर्ड कहीं नहीं पहुँचता, Cloudflare 1.1.1.1 / 1.0.0.1 इस्तेमाल करता है)। वहाँ भेजी गई जानकारी सर्वर तक नहीं पहुँच सकती, इसलिए उपयोगकर्ता नाम और पासवर्ड भी भेजे नहीं जाते। पता देने वाले से मौजूदा होस्ट पूछें या उनकी होस्ट सूची “सर्वरों की सूची का परीक्षण करें” में डालें।",
    "The on-demand library": "माँग पर उपलब्ध वीडियो लाइब्रेरी",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "पैनल ने HTTP {statusCode} का जवाब दिया, लेकिन प्लेलिस्ट JSON नहीं भेजा। कई पैनल 401/403/511/512 का इस्तेमाल “इस IP से अनुमति नहीं” या “गलत लॉगिन विवरण” के लिए करते हैं।",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "पैनल उपलब्ध है लेकिन उसने लॉगिन विवरण अस्वीकार किए: गलत उपयोगकर्ता नाम या पासवर्ड, समाप्त सदस्यता या बहुत ज़्यादा सक्रिय कनेक्शन।",
    "The panel returned data this client could not parse.":
        "पैनल ने ऐसा डेटा भेजा जिसे ऐप पढ़ नहीं सका।",
