    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "{count} पैनल आज़माए। उपयोगकर्ता नाम और पासवर्ड जाँचें या उन्नत सेटिंग में प्रदाता का सर्वर पता जोड़ें।",
