    "Username": "उपयोगकर्ता नाम",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "नतीजा: {host} ने दिए गए पोर्ट {port} और आम पैनल पोर्ट पर जवाब नहीं दिया। सर्वर ऑफ़लाइन या फ़ायरवॉल से अवरुद्ध हो सकता है, या पता गलत है।",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "नतीजा: सर्वर जवाब देता है (HTTP {status}), लेकिन Xtream पैनल की तरह नहीं। अक्सर वजह IP/नेटवर्क प्रतिबंध (401/403/511/512) या गलत पोर्ट होता है; ऊपर विवरण देखें।",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "नतीजा: पोर्ट {port} पर पैनल उपलब्ध है, लेकिन लॉगिन विवरण अस्वीकार किए गए — उपयोगकर्ता नाम या पासवर्ड गलत हो सकते हैं, सदस्यता समाप्त हो सकती है या बहुत ज़्यादा कनेक्शन सक्रिय हैं।",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "नतीजा: {host} किसी अस्थायी पते की ओर इशारा करता है (जब DNS रिकॉर्ड कहीं नहीं पहुँचता, Cloudflare 1.1.1.1 / 1.0.0.1 इस्तेमाल करता है)। अनुरोध सर्वर तक नहीं पहुँच सकते, इसलिए उपयोगकर्ता नाम और पासवर्ड भेजे नहीं जाते। पता देने वाले से मौजूदा पैनल होस्ट पूछें; अगर पहले इस्तेमाल किया गया ऐप अब भी लॉग इन कर पा रहा है, तो वह किसी दूसरे होस्ट से जुड़ा है।",
    "View & refresh": "देखें और ताज़ा करें",
