  "id": {
    "Account": "Akun",
    "Account & settings": "Akun & pengaturan",
    "Account expired on {date}": "Akun berakhir pada {date}",
    "All": "Semua",
    "All titles": "Semua judul",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Aplikasi yang mendukung Xtream Codes dapat menggunakan tautan ini. Tautan tersebut berisi nama pengguna dan kata sandi Anda; jaga kerahasiaannya dan jangan tempelkan di percakapan atau situs publik.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Tombol panah memindahkan fokus, Enter (atau OK pada remote) memilih, dan Esc/Back kembali. Di pemutar, tekan OK untuk menampilkan kontrol, lalu pilih tombol dengan panah dan tekan OK. Saat video difokuskan, ↑↓ mengganti saluran, sedangkan ←→ memajukan atau memundurkan video maupun mengubah volume siaran langsung; Enter/Space menjeda, M membisukan, dan C mengubah mode sinema. Remote Fire TV dan Android TV serta pengendali berbasis papan ketik dapat digunakan; gamepad yang tidak mengirim input papan ketik belum didukung.",
    "Back": "Kembali",
    "Back 10 s (←)": "Mundur 10 dtk (←)",
    "Back to sections": "Kembali ke bagian",
    "Big hero banner over per-category poster rails":
        "Banner utama besar di atas deretan poster per kategori",
    "Browse": "Jelajahi",
    "Browse all": "Jelajahi semua",
    "Cannot reach {server}: {reason}":
        "Tidak dapat mencapai {server}: {reason}",
    "Category column on the left, content on the right":
