    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Galat Cloudflare 1034 berarti catatan DNS domain mengarah ke alamat sementara (misalnya 1.1.1.1), sehingga permintaan tidak sampai ke server. Tidak ada aplikasi yang dapat masuk sebelum penyedia memperbaiki catatan tersebut; masalahnya bukan pada kredensial.",
