    "That address is a placeholder, not a server.":
        "Alamat tersebut adalah alamat sementara, bukan server.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Port ini menggunakan HTTP biasa, bukan TLS — hapus https:// (panel Xtream biasanya menggunakan http://host:8080). Aplikasi sudah mencoba lagi melalui http, jadi pesan ini berarti percobaan tersebut juga gagal.",
    "The account exists but its expiry date has passed.":
        "Akun ada, tetapi masa berlakunya telah habis.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Server sama sekali tidak merespons. Penyebab umum: nama host atau port salah, DNS mengarah ke alamat yang tidak aktif, firewall, atau panel tidak tersedia pada port tersebut.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Nama host mengarah ke alamat yang tidak dapat menjalankan panel (Cloudflare menggunakan 1.1.1.1 / 1.0.0.1 saat catatan DNS tidak mengarah ke server). Data yang dikirim ke sana tidak dapat mencapai server, sehingga nama pengguna dan kata sandi pun tidak terkirim. Mintalah alamat host saat ini kepada pihak yang memberikannya, atau tempel daftar host mereka ke “Uji daftar server”.",
    "The on-demand library": "Pustaka tayangan sesuai permintaan",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Panel merespons dengan HTTP {statusCode}, tetapi tidak mengirim JSON daftar putar. Banyak panel menggunakan 401/403/511/512 untuk menandakan “IP ini tidak diizinkan” atau “data masuk salah”.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Panel dapat dihubungi, tetapi menolak data masuk ini: nama pengguna atau kata sandi salah, langganan kedaluwarsa, atau terlalu banyak koneksi aktif.",
    "The panel returned data this client could not parse.":
        "Panel mengirim data yang tidak dapat dibaca aplikasi ini.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Alamat server “{server}” bukan URL yang valid ({reason}).",
