    "Username": "Nama pengguna",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Hasil: {host} tidak merespons pada port yang dimasukkan ({port}) maupun port panel yang umum. Server mungkin tidak aktif, diblokir firewall, atau alamatnya salah.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Hasil: server merespons (HTTP {status}), tetapi bukan sebagai panel Xtream. Biasanya karena pembatasan IP/jaringan (401/403/511/512) atau port yang salah; lihat rincian di atas.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Hasil: panel dapat dihubungi pada port {port}, tetapi menolak data masuk — nama pengguna atau kata sandi salah, langganan berakhir, atau terlalu banyak koneksi aktif.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Hasil: {host} mengarah ke alamat sementara (Cloudflare menggunakan 1.1.1.1 / 1.0.0.1 saat catatan DNS tidak mengarah ke server). Permintaan tidak dapat mencapai server di sana, sehingga nama pengguna dan kata sandi tidak terkirim. Mintalah host panel saat ini kepada pihak yang memberi Anda alamat; jika aplikasi lama masih dapat masuk, aplikasi itu terhubung ke host lain.",
    "View & refresh": "Tampilan & muat ulang",
