  "ja": {
    "Account": "アカウント",
    "Account & settings": "アカウントと設定",
    "Account expired on {date}": "アカウントの有効期限は{date}に切れました",
    "All": "すべて",
    "All titles": "すべてのタイトル",
    "Amber Noir": "アンバー・ノワール",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Xtream Codesに対応したクライアントで利用できます。ユーザー名とパスワードが含まれるため、機密情報として扱い、チャットや公開サイトに貼り付けないでください。",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "矢印キーでフォーカスを移動し、Enterキー（またはリモコンのOK）で選択、Esc/戻るで前の画面に戻ります。プレーヤーではOKを押すと操作ボタンが表示されます。矢印キーでボタンを選び、OKで実行します。動画にフォーカスがある場合、↑↓でチャンネルを切り替え、←→でシークまたはライブ放送の音量を調整します。Enter/Spaceで一時停止、Mでミュート、Cでシネマモードを切り替えます。Fire TV / Android TVのリモコンとキーボード式コントローラーに対応しています。キーボード入力を送らないゲームパッドにはまだ対応していません。",
    "Back": "戻る",
    "Back 10 s (←)": "10秒戻る（←）",
    "Back to sections": "セクションに戻る",
    "Big hero banner over per-category poster rails":
        "カテゴリ別のポスター一覧の上に大きなバナーを表示",
    "Browse": "閲覧",
