    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflareエラー1034は、ドメインのDNSレコードが仮のアドレス（例: 1.1.1.1）を指しており、リクエストがサーバーに届かないことを意味します。提供元がDNSレコードを修正するまでログインできません。認証情報に問題があるわけではありません。",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it":
