        "デスクトップではタブとカテゴリ一覧、スマートフォンでは下部ナビゲーション",
    "Test a list of servers": "サーバーのリストをテストする",
    "Test these servers": "これらのサーバーをテストする",
    "Testing…": "テスト中…",
    "That address is a placeholder, not a server.": "そのアドレスはサーバーではなく仮のアドレスです。",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "このポートはTLSではなく平文HTTPを使用しています — https://を外してください（Xtreamパネルは通常http://host:8080です）。アプリはすでにhttpで再試行しているため、このメッセージが表示された場合はhttpでの接続も失敗しています。",
    "The account exists but its expiry date has passed.":
        "アカウントは存在しますが、有効期限が切れています。",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "ホストから応答がありません。通常の原因はホスト名やポートの誤り、DNSが無効な宛先を指していること、ファイアウォール、またはパネルがそのポートで待ち受けていないことです。",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "ホスト名はパネルを実行できないアドレスに解決されています（DNSレコードの宛先がない場合、Cloudflareは1.1.1.1 / 1.0.0.1を使用します）。そのアドレスにはサーバーがないため、ユーザー名とパスワードも送信されません。アドレスの提供元に現在のホスト名を確認するか、提供元のホスト一覧を「サーバーのリストをテストする」に貼り付けてください。",
    "The on-demand library": "オンデマンドライブラリ",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "パネルはHTTP {statusCode}を返しましたが、プレイリストのJSONは返しませんでした。多くのパネルは「このIPからのアクセスは禁止」や「認証情報が無効」を示すために401/403/511/512を使用します。",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.":
        "パネルに接続できましたが、認証情報は拒否されました。ユーザー名やパスワードの誤り、契約期限切れ、または接続数の上限超過が考えられます。",
    "The panel returned data this client could not parse.":
        "パネルからこのクライアントで解析できないデータが返されました。",
    "The server address \"{server}\" is not a valid URL ({reason}).":
