    "Username": "ユーザー名",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "診断結果: {host}から応答がありません（入力したポート{port}と通常のパネル用ポートを確認しました）。ホストがオフラインかファイアウォールで遮断されている、またはアドレスが間違っています。",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "診断結果: ホストは応答しています（HTTP {status}）が、Xtreamパネルではありません。多くの場合、IP/ネットワークによる制限（401/403/511/512）かポートの誤りが原因です。詳細は上記を確認してください。",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "診断結果: ポート{port}のパネルに接続できましたが、認証情報が拒否されました。ユーザー名やパスワードの誤り、契約期限切れ、または接続数の上限超過が考えられます。",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "診断結果: {host}は仮のアドレスに解決されています（DNSレコードの宛先がない場合、Cloudflareは1.1.1.1 / 1.0.0.1を使用します）。リクエストはサーバーに届かず、ユーザー名やパスワードも送信されません。アドレスの提供元に修正を依頼し、現在のパネルのホスト名を確認してください。以前使用していたアプリでまだログインできる場合、そのアプリは別のホストに接続しています。",
