  "ko": {
    "Account": "계정",
    "Account & settings": "계정 및 설정",
    "Account expired on {date}": "계정 만료일: {date}",
    "All": "전체",
    "All titles": "모든 콘텐츠",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Xtream Codes를 지원하는 클라이언트에서 사용할 수 있습니다. 사용자 이름과 비밀번호가 포함되어 있으므로 기밀 정보로 취급하고 채팅이나 공개 사이트에 붙여넣지 마세요.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "화살표 키로 포커스를 이동하고 Enter(또는 리모컨의 OK)로 선택하며 Esc/뒤로 가기로 돌아갑니다. 플레이어에서 OK를 누르면 조작 버튼이 나타납니다. 화살표 키로 버튼을 선택하고 OK로 실행하세요. 영상에 포커스가 있을 때 ↑↓로 채널을 바꾸고 ←→로 탐색하거나 라이브 방송의 음량을 조절합니다. Enter/Space로 일시 정지, M으로 음소거, C로 시네마 모드를 전환합니다. Fire TV / Android TV 리모컨과 키보드 방식 컨트롤러를 사용할 수 있습니다. 키보드 입력을 보내지 않는 게임패드는 아직 지원되지 않습니다.",
    "Back": "뒤로",
    "Back 10 s (←)": "10초 뒤로 (←)",
    "Back to sections": "섹션으로 돌아가기",
    "Big hero banner over per-category poster rails":
        "카테고리별 포스터 목록 위에 큰 대표 배너 표시",
    "Browse": "둘러보기",
    "Browse all": "모두 둘러보기",
    "Cannot reach {server}: {reason}": "{server}에 연결할 수 없음: {reason}",
    "Category column on the left, content on the right":
        "왼쪽에 카테고리, 오른쪽에 콘텐츠 표시",
    "Channels, movies, series": "채널, 영화, 시리즈",
    "Channels, now and next": "채널, 현재 및 다음 프로그램",
    "Check without a login": "로그인 없이 확인",
    "Checking panels…": "패널 확인 중…",
    "Checking…": "확인 중…",
    "Cinema": "시네마 모드",
    "Cinema (C)": "시네마 모드 (C)",
    "Classic": "클래식",
    "Clear search": "검색어 지우기",
    "Close": "닫기",
    "Cloudflare could not reach the origin ({server}): error code 1034":
        "Cloudflare가 원본 서버({server})에 연결할 수 없음: 오류 코드 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare 오류 1034는 도메인의 DNS 레코드가 임시 주소(예: 1.1.1.1)를 가리켜 요청이 서버에 도달하지 못한다는 뜻입니다. 제공업체가 레코드를 수정하기 전에는 로그인할 수 없습니다. 로그인 정보에는 문제가 없습니다.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it":
        "Cloudflare 오류 1034 — DNS 레코드가 임시 주소를 가리키며 해당 주소에 서버가 없습니다",
    "Comfortable": "여유로운",
    "Comfortable spacing": "여유로운 간격",
    "Compact": "간결한",
    "Compact section tiles with artwork and a remote-friendly focus path":
        "이미지가 있는 간결한 섹션 타일과 리모컨으로 조작하기 쉬운 포커스 순서",
    "Compact spacing": "좁은 간격",
    "Compact spacing (fits more)": "좁은 간격 (더 많이 표시)",
    "Connections": "연결",
    "Could not load episodes. Check your connection and retry.":
