    "Could not parse JSON from {server}": "{server}의 JSON을 파싱할 수 없음",
    "DNS for {host} points at {address}, a placeholder address — no server is reachable there":
        "{host}의 DNS가 임시 주소인 {address}를 가리킵니다 — 해당 주소에서 서버에 연결할 수 없습니다",
