  "zh": {
    "Account": "账户",
    "Account & settings": "账户与设置",
    "Account expired on {date}": "账户已于{date}过期",
    "All": "全部",
    "All titles": "所有内容",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "任何支持 Xtream Codes 的客户端都可以使用这些链接。链接中包含您的用户名和密码，请将其视为机密信息，不要粘贴到聊天或公共网站中。",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "方向键用于移动焦点，Enter（或遥控器上的 OK）用于确认，Esc/返回用于返回上一页。在播放器中，按 OK 显示控件，然后用方向键选择按钮并按 OK 执行。当焦点位于视频上时，↑↓切换频道，←→快进快退或调整直播音量；Enter/Space 暂停，M 静音，C 切换影院模式。支持 Fire TV / Android TV 遥控器和键盘式控制器；不发送键盘事件的普通游戏手柄暂未适配。",
    "Back": "返回",
    "Back 10 s (←)": "后退 10 秒（←）",
    "Back to sections": "返回分区",
    "Big hero banner over per-category poster rails": "分类海报列表上方的大幅主视觉横幅",
    "Browse": "浏览",
    "Browse all": "浏览全部",
    "Cannot reach {server}: {reason}": "无法连接到{server}：{reason}",
    "Category column on the left, content on the right": "左侧为分类栏，右侧为内容",
    "Channels, movies, series": "频道、电影、剧集",
    "Channels, now and next": "频道、当前和接下来的节目",
    "Check without a login": "不登录检查",
    "Checking panels…": "正在检查面板…",
    "Checking…": "正在检查…",
    "Cinema": "影院模式",
    "Cinema (C)": "影院模式（C）",
    "Classic": "经典",
    "Clear search": "清除搜索",
    "Close": "关闭",
    "Cloudflare could not reach the origin ({server}): error code 1034":
        "Cloudflare 无法连接到源服务器（{server}）：错误代码 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare 错误 1034 表示域名的 DNS 记录指向占位地址（例如 1.1.1.1），因此请求无法到达服务器。服务提供方修复该记录之前，任何客户端都无法登录；问题不在于登录凭据。",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it":
        "Cloudflare 错误 1034 — DNS 记录指向占位地址，该地址后面没有服务器",
