    "Testing…": "正在测试…",
    "That address is a placeholder, not a server.": "此地址是占位地址，不是服务器。",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "该端口使用普通 HTTP，而非 TLS — 请移除 https://（Xtream 面板通常使用 http://host:8080）。应用已尝试通过 http 重连，因此看到此消息表示 http 连接也失败了。",
    "The account exists but its expiry date has passed.": "账户存在，但已超过有效期。",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.":
        "主机没有响应。常见原因包括主机名或端口错误、DNS 指向不可用的地址、防火墙拦截，或面板未在该端口监听。",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "主机名解析到无法运行面板的地址（DNS 记录未指向有效位置时，Cloudflare 使用 1.1.1.1 / 1.0.0.1）。发送到该地址的请求无法到达服务器，因此用户名和密码也不会被传输。请向提供地址的人索取当前主机地址，或将对方提供的主机列表粘贴到“测试服务器列表”中。",
    "The on-demand library": "点播内容库",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "面板返回了 HTTP {statusCode}，但没有返回播放列表 JSON。许多面板使用 401/403/511/512 表示“此 IP 不允许访问”或“登录凭据错误”。",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.":
        "可以连接到面板，但登录凭据遭到拒绝：用户名或密码错误、订阅过期，或已达到连接数上限。",
    "The panel returned data this client could not parse.":
        "面板返回了该客户端无法解析的数据 。",
