    "Username": "用户名",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.":
        "诊断结果：{host}没有响应（已检查输入的端口{port}及常见面板端口）。主机可能离线、被防火墙拦截，或地址有误。",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "诊断结果：主机有响应（HTTP {status}），但不是 Xtream 面板。通常是 IP/网络访问限制（401/403/511/512）或端口错误；详情请查看上方信息。",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.":
        "诊断结果：可以连接到端口{port}上的面板，但登录凭据遭到拒绝，可能是用户名或密码错误、订阅过期，或连接数过多。",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "诊断结果：{host}解析到占位地址（DNS 记录未指向有效位置时，Cloudflare 使用 1.1.1.1 / 1.0.0.1）。请求无法到达服务器，因此用户名和密码也不会被发送。请联系提供地址的人修复，并索取当前面板主机地址。如果之前使用的应用仍能登录，说明它连接的是另一台主机。",
