  "sv": {
    "Account": "Konto",
    "Account & settings": "Konto och inställningar",
    "Account expired on {date}": "Kontot upphörde att gälla {date}",
    "All": "Alla",
    "All titles": "Alla titlar",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Alla appar som stöder Xtream Codes kan använda dessa länkar. De innehåller ditt användarnamn och lösenord. Behandla dem som hemliga och klistra inte in dem i chattar eller på offentliga webbplatser.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Piltangenterna flyttar fokus, Enter (eller OK på fjärrkontrollen) aktiverar och Esc/Tillbaka går tillbaka. Tryck på OK i spelaren för att visa kontrollerna. Välj sedan en knapp med pilarna och aktivera den med OK. När videon har fokus byter ↑↓ kanal och ←→ spolar eller ändrar volymen för direktsändning. Enter/Blanksteg pausar, M stänger av ljudet och C växlar bioläge. Fjärrkontroller för Fire TV/Android TV och tangentbordsliknande handkontroller fungerar; vanliga spelkontroller utan tangentbordshändelser stöds ännu inte.",
    "Back": "Tillbaka",
    "Back 10 s (←)": "Bakåt 10 s (←)",
    "Back to sections": "Tillbaka till sektionerna",
    "Big hero banner over per-category poster rails":
        "Stor huvudbanner ovanför kategoriernas affischrader",
    "Browse": "Utforska",
