        "Cloudflare kunde inte nå ursprungsservern ({server}): felkod 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare-fel 1034 betyder att domänens DNS-post pekar på en platshållaradress (t.ex. 1.1.1.1), så inga förfrågningar når en server. Ingen app kan logga in förrän leverantören rättar DNS-posten – det är inte inloggningsuppgifterna som är problemet.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Cloudflare-fel 1034 – DNS-posten pekar på en platshållare utan någon server bakom",
