    "Test a list of servers": "Testa en lista med servrar",
    "Test these servers": "Testa dessa servrar",
    "Testing…": "Testar…",
    "That address is a placeholder, not a server.":
        "Adressen är en platshållare, inte en server.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Den porten använder vanlig HTTP, inte TLS – ta bort https:// (Xtream-paneler använder normalt http://host:8080). Appen försöker redan igen via http, så om du ser detta misslyckades även HTTP-försöket.",
    "The account exists but its expiry date has passed.":
        "Kontot finns men giltighetstiden har gått ut.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Värden svarade inte alls. Vanliga orsaker är fel värdnamn eller port, DNS som pekar fel, en brandvägg eller att panelen inte lyssnar på porten.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Värdnamnet pekar på en adress som inte kan köra en panel (Cloudflare använder 1.1.1.1 / 1.0.0.1 när en DNS-post inte pekar någonstans). Ingenting som skickas dit når en server, så användarnamn och lösenord överförs aldrig. Be den som gav dig adressen om den aktuella värden, eller klistra in deras värdlista i ”Testa en lista med servrar”.",
    "The on-demand library": "Biblioteket med innehåll på begäran",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Panelen svarade med HTTP {statusCode}, men inte med JSON för spellistan. Många paneler använder 401/403/511/512 för ”inte tillåtet från denna IP-adress” eller ”fel inloggningsuppgifter”.",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Panelen går att nå men avvisade inloggningsuppgifterna: fel användarnamn/lösenord, utgånget abonnemang eller för många aktiva anslutningar.",
    "The panel returned data this client could not parse.":
        "Panelen returnerade data som appen inte kunde tolka.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Serveradressen ”{server}” är inte en giltig URL ({reason}).",
