        "Tidsgränsen överskreds vid anslutning till {server}",
    "Toggle list / grid": "Växla mellan lista och rutnät",
    "Toggle spacing": "Växla avstånd",
    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Testade {count} paneler. Kontrollera användarnamn och lösenord eller lägg till leverantörens serveradress under Avancerat.",
    "Trying {panel} ({current}/{total})…":
