        "Använd samma abonnemang i en annan app",
    "Use this server": "Använd den här servern",
    "Username": "Användarnamn",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Resultat: inget svar från {host} (angiven port {port} och vanliga panelportar). Värden är offline eller blockerad av en brandvägg, eller så är adressen fel.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Resultat: värden svarar (HTTP {status}), men inte som en Xtream-panel. Oftast beror det på IP-/nätverksbegränsning (401/403/511/512) eller fel port – se detaljerna ovan.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Resultat: panelen går att nå på port {port} men avvisade inloggningsuppgifterna – fel användarnamn/lösenord, utgånget abonnemang eller för många anslutningar.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Resultat: {host} pekar på en platshållaradress (Cloudflare använder 1.1.1.1 / 1.0.0.1 när en DNS-post inte pekar någonstans). Ingen begäran når en server där, så användarnamn och lösenord skickas aldrig. Den som gav dig adressen måste rätta detta – be om aktuell panelvärd. Om en tidigare app fortfarande kan logga in använder den en annan värd.",
    "View & refresh": "Visa och uppdatera",
