  "el": {
    "Account": "Λογαριασμός",
    "Account & settings": "Λογαριασμός και ρυθμίσεις",
    "Account expired on {date}": "Ο λογαριασμός έληξε στις {date}",
    "All": "Όλα",
    "All titles": "Όλοι οι τίτλοι",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.": "Κάθε εφαρμογή που υποστηρίζει Xtream Codes μπορεί να χρησιμοποιήσει αυτούς τους συνδέσμους. Περιέχουν το όνομα χρήστη και τον κωδικό πρόσβασής σας. Κρατήστε τους μυστικούς και μην τους επικολλάτε σε συνομιλίες ή δημόσιους ιστότοπους.",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "Τα βέλη μετακινούν την εστίαση, το Enter (ή το OK του τηλεχειριστηρίου) ενεργοποιεί και το Esc/Back επιστρέφει. Στη συσκευή αναπαραγωγής πατήστε OK για να εμφανιστούν τα χειριστήρια. Επιλέξτε κουμπί με τα βέλη και ενεργοποιήστε το με OK. Όταν είναι εστιασμένο το βίντεο, τα ↑↓ αλλάζουν κανάλι και τα ←→ μετακινούν την αναπαραγωγή ή αλλάζουν την ένταση της ζωντανής μετάδοσης. Το Enter/Space κάνει παύση, το M σιγεί τον ήχο και το C εναλλάσσει τη λειτουργία κινηματογράφου. Λειτουργούν τηλεχειριστήρια Fire TV/Android TV και χειριστήρια τύπου πληκτρολογίου· τα απλά gamepad χωρίς συμβάντα πληκτρολογίου δεν υποστηρίζονται ακόμη.",
    "Back": "Πίσω",
    "Back 10 s (←)": "Πίσω 10 δ. (←)",
    "Back to sections": "Πίσω στις ενότητες",
    "Big hero banner over per-category poster rails":
        "Μεγάλο κεντρικό πανό πάνω από σειρές αφισών ανά κατηγορία",
    "Browse": "Περιήγηση",
    "Browse all": "Περιήγηση σε όλα",
    "Cannot reach {server}: {reason}":
        "Δεν είναι δυνατή η σύνδεση με {server}: {reason}",
    "Category column on the left, content on the right":
        "Στήλη κατηγοριών αριστερά, περιεχόμενο δεξιά",
    "Channels, movies, series": "Κανάλια, ταινίες, σειρές",
    "Channels, now and next": "Κανάλια, τώρα και στη συνέχεια",
    "Check without a login": "Έλεγχος χωρίς σύνδεση",
    "Checking panels…": "Έλεγχος πάνελ…",
    "Checking…": "Έλεγχος…",
    "Cinema": "Λειτουργία κινηματογράφου",
    "Cinema (C)": "Λειτουργία κινηματογράφου (C)",
    "Classic": "Κλασικό",
    "Clear search": "Εκκαθάριση αναζήτησης",
    "Close": "Κλείσιμο",
    "Cloudflare could not reach the origin ({server}): error code 1034": "Το Cloudflare δεν μπόρεσε να συνδεθεί με τον διακομιστή προέλευσης ({server}): κωδικός σφάλματος 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Το σφάλμα Cloudflare 1034 σημαίνει ότι η εγγραφή DNS του τομέα δείχνει σε διεύθυνση-κράτησης θέσης (π.χ. 1.1.1.1), οπότε κανένα αίτημα δεν φτάνει σε διακομιστή. Καμία εφαρμογή δεν μπορεί να συνδεθεί έως ότου ο πάροχος διορθώσει την εγγραφή· το πρόβλημα δεν είναι τα διαπιστευτήρια.",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it": "Σφάλμα Cloudflare 1034 — η εγγραφή DNS δείχνει σε διεύθυνση-κράτησης θέσης χωρίς διακομιστή πίσω της",
    "Comfortable": "Άνετο",
    "Comfortable spacing": "Άνετη απόσταση",
    "Compact": "Συμπαγές",
    "Compact section tiles with artwork and a remote-friendly focus path": "Συμπαγή πλακίδια ενοτήτων με εικόνες και πλοήγηση εστίασης φιλική προς τηλεχειριστήριο",
    "Compact spacing": "Συμπαγής απόσταση",
    "Compact spacing (fits more)": "Συμπαγής απόσταση (χωρούν περισσότερα)",
    "Connections": "Συνδέσεις",
    "Could not load episodes. Check your connection and retry.": "Δεν ήταν δυνατή η φόρτωση επεισοδίων. Ελέγξτε τη σύνδεσή σας και δοκιμάστε ξανά.",
