    "S{season}E{episode} · {title}": "S{season}E{episode} · {title}",
    "TLS failed: {error}": "Αποτυχία TLS: {error}",
    "TLS handshake with {host}:{port} failed: {reason}":
        "Αποτυχία χειραψίας TLS με {host}:{port}: {reason}",
    "Tab strip and category rail on desktop, bottom nav on phones": "Καρτέλες και σειρά κατηγοριών στον υπολογιστή, πλοήγηση κάτω στο κινητό",
    "Test a list of servers": "Έλεγχος λίστας διακομιστών",
    "Test these servers": "Έλεγχος αυτών των διακομιστών",
    "Testing…": "Έλεγχος…",
    "That address is a placeholder, not a server.":
        "Αυτή η διεύθυνση είναι διεύθυνση-κράτησης θέσης, όχι διακομιστής.",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "Αυτή η θύρα χρησιμοποιεί απλό HTTP, όχι TLS — αφαιρέστε το https:// (τα πάνελ Xtream χρησιμοποιούν συνήθως http://host:8080). Η εφαρμογή δοκιμάζει ήδη ξανά μέσω http, επομένως απέτυχε και αυτή η προσπάθεια.",
    "The account exists but its expiry date has passed.":
        "Ο λογαριασμός υπάρχει αλλά έχει λήξει.",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.": "Ο διακομιστής δεν απάντησε καθόλου. Συνήθεις αιτίες: λάθος όνομα ή θύρα, DNS που δείχνει σε μη διαθέσιμη διεύθυνση, τείχος προστασίας ή το πάνελ δεν ακούει σε αυτή τη θύρα.",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "Το όνομα διακομιστή αντιστοιχεί σε διεύθυνση όπου δεν μπορεί να λειτουργήσει πάνελ (το Cloudflare χρησιμοποιεί 1.1.1.1 / 1.0.0.1 όταν μια εγγραφή DNS δεν δείχνει πουθενά). Τίποτα που αποστέλλεται εκεί δεν φτάνει σε διακομιστή, επομένως το όνομα χρήστη και ο κωδικός δεν μεταδίδονται καν. Ζητήστε από αυτόν που σας έδωσε τη διεύθυνση το τρέχον όνομα διακομιστή ή επικολλήστε τη λίστα του στο «Έλεγχος λίστας διακομιστών».",
    "The on-demand library": "Η βιβλιοθήκη περιεχομένου κατ’ απαίτηση",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "Το πάνελ απάντησε με HTTP {statusCode}, αλλά όχι με JSON λίστας αναπαραγωγής. Πολλά πάνελ χρησιμοποιούν 401/403/511/512 για «δεν επιτρέπεται από αυτή την IP» ή «λάθος διαπιστευτήρια».",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.": "Το πάνελ είναι προσβάσιμο αλλά απέρριψε τα διαπιστευτήρια: λάθος όνομα χρήστη/κωδικός, ληγμένη συνδρομή ή πάρα πολλές ενεργές συνδέσεις.",
    "The panel returned data this client could not parse.":
        "Το πάνελ επέστρεψε δεδομένα που η εφαρμογή δεν μπόρεσε να αναλύσει.",
    "The server address \"{server}\" is not a valid URL ({reason}).":
        "Η διεύθυνση διακομιστή «{server}» δεν είναι έγκυρο URL ({reason}).",
    "Theme": "Θέμα",
    "This series has no episodes listed.":
