    "Tried {count} panels. Check the username and password, or add the provider’s server address under Advanced.": "Ελέγχθηκαν {count} πάνελ. Ελέγξτε το όνομα χρήστη και τον κωδικό ή προσθέστε τη διεύθυνση του παρόχου στις Σύνθετες ρυθμίσεις.",
    "Trying {panel} ({current}/{total})…":
        "Δοκιμή {panel} ({current}/{total})…",
    "Unexpected login response": "Μη αναμενόμενη απάντηση σύνδεσης",
