    "Use this server": "Χρήση αυτού του διακομιστή",
    "Username": "Όνομα χρήστη",
    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.": "Αποτέλεσμα: καμία απάντηση από {host} (δηλωμένη θύρα {port} και συνήθεις θύρες πάνελ). Ο διακομιστής είναι εκτός σύνδεσης ή πίσω από τείχος προστασίας, ή η διεύθυνση είναι λάθος.",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "Αποτέλεσμα: ο διακομιστής απαντά (HTTP {status}), αλλά όχι ως πάνελ Xtream. Συνήθως πρόκειται για περιορισμό IP/δικτύου (401/403/511/512) ή λάθος θύρα — δείτε τις λεπτομέρειες παραπάνω.",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.": "Αποτέλεσμα: το πάνελ είναι προσβάσιμο στη θύρα {port}, αλλά απέρριψε τα διαπιστευτήρια — λάθος όνομα χρήστη/κωδικός, ληγμένη συνδρομή ή πάρα πολλές συνδέσεις.",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "Αποτέλεσμα: το {host} αντιστοιχεί σε διεύθυνση-κράτησης θέσης (το Cloudflare χρησιμοποιεί 1.1.1.1 / 1.0.0.1 όταν μια εγγραφή DNS δεν δείχνει πουθενά). Κανένα αίτημα δεν φτάνει εκεί σε διακομιστή, οπότε το όνομα χρήστη και ο κωδικός δεν αποστέλλονται. Αυτό πρέπει να διορθωθεί από αυτόν που σας έδωσε τη διεύθυνση — ζητήστε την τρέχουσα διεύθυνση του πάνελ. Αν κάποια παλαιότερη εφαρμογή εξακολουθεί να συνδέεται, χρησιμοποιεί διαφορετικό διακομιστή.",
    "View & refresh": "Προβολή και ανανέωση",
