  "zh-Hant": {
    "Account": "帳戶",
    "Account & settings": "帳戶與設定",
    "Account expired on {date}": "帳戶已於 {date} 到期",
    "All": "全部",
    "All titles": "所有節目",
    "Amber Noir": "Amber Noir",
    "Any client that speaks Xtream Codes can use these. They embed your username and password, so treat them like a secret and do not paste them into chats or public sites.":
        "任何支援 Xtream Codes 的用戶端都能使用這些連結。連結包含您的使用者名稱和密碼，請妥善保密，不要貼到聊天或公開網站。",
    "Arrows move the focus, Enter (or the remote’s OK) activates, Esc/Back goes back. In the player, press OK to reveal the controls, then use arrows to choose a button and OK to activate it. With the video focused, ↑↓ switch channel, ←→ seek or change live volume; Enter/Space pauses, M mutes and C toggles cinema. Fire TV / Android TV remotes and keyboard-style controllers work; raw gamepads with no keyboard events are not mapped yet.": "方向鍵可移動焦點，Enter（或遙控器的 OK）可啟用項目，Esc/返回可返回上一頁。在播放器中按 OK 顯示控制項，再用方向鍵選取按鈕並按 OK 啟用。影片取得焦點時，↑↓ 可切換頻道，←→ 可快轉倒轉或調整直播音量；Enter/空白鍵可暫停、M 可靜音、C 可切換劇院模式。支援 Fire TV / Android TV 遙控器和模擬鍵盤的控制器；尚未支援不會傳送鍵盤事件的一般遊戲手把。",
    "Back": "返回",
    "Back 10 s (←)": "倒轉 10 秒 (←)",
    "Back to sections": "返回分類",
    "Big hero banner over per-category poster rails": "大型主視覺橫幅與各分類海報列",
    "Browse": "瀏覽",
    "Browse all": "瀏覽全部",
    "Cannot reach {server}: {reason}": "無法連線至 {server}：{reason}",
    "Category column on the left, content on the right": "左側分類欄，右側內容",
    "Channels, movies, series": "頻道、電影、影集",
    "Channels, now and next": "頻道、目前與接下來的節目",
    "Check without a login": "免登入檢查",
    "Checking panels…": "正在檢查服務面板…",
    "Checking…": "正在檢查…",
    "Cinema": "劇院模式",
    "Cinema (C)": "劇院模式 (C)",
    "Classic": "經典",
    "Clear search": "清除搜尋",
    "Close": "關閉",
    "Cloudflare could not reach the origin ({server}): error code 1034":
        "Cloudflare 無法連線至來源伺服器 ({server})：錯誤代碼 1034",
    "Cloudflare error 1034 means the domain's DNS record points at a placeholder address (e.g. 1.1.1.1), so no request ever reaches a server. No client can log in until the provider fixes that record — the credentials are not the problem.": "Cloudflare 錯誤 1034 表示網域的 DNS 紀錄指向佔位位址（例如 1.1.1.1），因此請求無法到達伺服器。在供應商修正該紀錄前，任何用戶端都無法登入；問題不在登入憑證。",
    "Cloudflare error 1034 — the DNS record points at a placeholder, nothing is listening behind it":
        "Cloudflare 錯誤 1034 — DNS 紀錄指向佔位位址，後方沒有伺服器",
    "Comfortable": "寬鬆",
    "Comfortable spacing": "寬鬆間距",
    "Compact": "精簡",
    "Compact section tiles with artwork and a remote-friendly focus path":
        "精簡分類圖塊，搭配圖片及適合遙控器操作的焦點順序",
    "Compact spacing": "精簡間距",
