    "Testing…": "正在測試…",
    "That address is a placeholder, not a server.": "該位址是佔位位址，不是伺服器。",
    "That port speaks plain HTTP, not TLS — drop the https:// (Xtream panels are normally http://host:8080). The app already retries over http, so reaching this message means the http attempt failed too.": "該連接埠使用一般 HTTP，而非 TLS；請移除 https://（Xtream 服務面板通常使用 http://host:8080）。應用程式已嘗試透過 http 重試，因此看到此訊息代表該嘗試也失敗了。",
    "The account exists but its expiry date has passed.": "帳戶存在，但已超過到期日。",
    "The host did not answer at all. Usual causes: wrong hostname/port, DNS pointing somewhere dead, firewall, or the panel not listening on that port.":
        "主機完全沒有回應。常見原因：主機名稱或連接埠錯誤、DNS 指向無效位址、防火牆阻擋，或服務面板未監聽該連接埠。",
    "The hostname resolves to an address that cannot run a panel (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). Nothing sent there can reach a server, so the username and password are never even transmitted. Ask whoever supplied the address for the current host, or paste their host list into \"Test a list of servers\".": "主機名稱解析到無法執行服務面板的位址（DNS 紀錄未指向有效伺服器時，Cloudflare 會使用 1.1.1.1 / 1.0.0.1）。傳送至該位址的資料無法到達伺服器，因此使用者名稱和密碼根本不會傳送出去。請向提供位址的人索取目前的主機名稱，或將對方提供的主機清單貼到「測試伺服器清單」。",
    "The on-demand library": "隨選內容庫",
    "The panel answered with HTTP {statusCode} but not with playlist JSON. Many panels use 401/403/511/512 for \"not allowed from this IP\" or \"bad credentials\".": "服務面板回傳 HTTP {statusCode}，但未回傳播放清單 JSON。許多服務面板使用 401/403/511/512 表示「不允許此 IP 存取」或「登入憑證錯誤」。",
    "The panel is reachable and refused these credentials: wrong username/password, expired subscription, or too many connections in use.":
        "服務面板可連線，但拒絕了登入憑證：使用者名稱或密碼錯誤、訂閱已到期，或同時連線數過多。",
    "The panel returned data this client could not parse.":
