    "Verdict: nothing answered on {host} (typed port {port} and the usual panel ports). Either the host is offline or firewalled, or the address is wrong.":
        "診斷結果：{host} 沒有回應（已測試指定的連接埠 {port} 和常用的服務面板連接埠）。主機可能離線、遭防火牆阻擋，或位址錯誤。",
    "Verdict: the host answers (HTTP {status}) but not as an Xtream panel. Most often that is an IP/network gate (401/403/511/512) or a wrong port — the detail lines above say which.": "診斷結果：主機有回應（HTTP {status}），但不是 Xtream 服務面板。最常見的原因是 IP／網路存取限制（401/403/511/512）或連接埠錯誤；詳情請見上方。",
    "Verdict: the panel is reachable on port {port} but refused these credentials — wrong username/password, an expired subscription, or too many connections.":
        "診斷結果：可透過連接埠 {port} 連線至服務面板，但登入憑證遭拒；可能是使用者名稱或密碼錯誤、訂閱已到期，或連線數過多。",
    "Verdict: {host} resolves to a placeholder address (Cloudflare uses 1.1.1.1 / 1.0.0.1 when a DNS record points nowhere). No request can reach a server there, so the username and password are never even sent. This has to be fixed by whoever gave you the address — ask them for the current panel host; if an app you used before still logs in, it is talking to a different host.": "診斷結果：{host} 解析到佔位位址（DNS 紀錄未指向有效伺服器時，Cloudflare 會使用 1.1.1.1 / 1.0.0.1）。請求無法透過該位址到達伺服器，因此使用者名稱和密碼根本不會傳送出去。請向提供位址的人索取目前的服務面板主機；如果您以前使用的應用程式仍能登入，表示它連線到另一台主機。",
